# ! [doc = " Generate files suitable for use with [Graphviz](https://www.graphviz.org/)"] # ! [doc = ""] # ! [doc = " The `render` function generates output (e.g., an `output.dot` file) for"] # ! [doc = " use with [Graphviz](https://www.graphviz.org/) by walking a labeled"] # ! [doc = " graph. (Graphviz can then automatically lay out the nodes and edges"] # ! [doc = " of the graph, and also optionally render the graph as an image or"] # ! [doc = " other [output formats](https://www.graphviz.org/docs/outputs), such as SVG.)"] # ! [doc = ""] # ! [doc = " Rather than impose some particular graph data structure on clients,"] # ! [doc = " this library exposes two traits that clients can implement on their"] # ! [doc = " own structs before handing them over to the rendering function."] # ! [doc = ""] # ! [doc = " Note: This library does not yet provide access to the full"] # ! [doc = " expressiveness of the [DOT language](https://www.graphviz.org/doc/info/lang.html)."] # ! [doc = " For example, there are many [attributes](https://www.graphviz.org/doc/info/attrs.html)"] # ! [doc = " related to providing layout hints (e.g., left-to-right versus top-down, which"] # ! [doc = " algorithm to use, etc). The current intention of this library is to"] # ! [doc = " emit a human-readable .dot file with very regular structure suitable"] # ! [doc = " for easy post-processing."] # ! [doc = ""] # ! [doc = " # Examples"] # ! [doc = ""] # ! [doc = " The first example uses a very simple graph representation: a list of"] # ! [doc = " pairs of ints, representing the edges (the node set is implicit)."] # ! [doc = " Each node label is derived directly from the int representing the node,"] # ! [doc = " while the edge labels are all empty strings."] # ! [doc = ""] # ! [doc = " This example also illustrates how to use `Cow<[T]>` to return"] # ! [doc = " an owned vector or a borrowed slice as appropriate: we construct the"] # ! [doc = " node vector from scratch, but borrow the edge list (rather than"] # ! [doc = " constructing a copy of all the edges from scratch)."] # ! [doc = ""] # ! [doc = " The output from this example renders five nodes, with the first four"] # ! [doc = " forming a diamond-shaped acyclic graph and then pointing to the fifth"] # ! [doc = " which is cyclic."] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " #![feature(rustc_private)]"] # ! [doc = ""] # ! [doc = " use std::io::Write;"] # ! [doc = " use rustc_graphviz as dot;"] # ! [doc = ""] # ! [doc = " type Nd = isize;"] # ! [doc = " type Ed = (isize,isize);"] # ! [doc = " struct Edges(Vec<Ed>);"] # ! [doc = ""] # ! [doc = " pub fn render_to<W: Write>(output: &mut W) {"] # ! [doc = "     let edges = Edges(vec![(0,1), (0,2), (1,3), (2,3), (3,4), (4,4)]);"] # ! [doc = "     dot::render(&edges, output).unwrap()"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl<'a> dot::Labeller<'a> for Edges {"] # ! [doc = "     type Node = Nd;"] # ! [doc = "     type Edge = Ed;"] # ! [doc = "     fn graph_id(&'a self) -> dot::Id<'a> { dot::Id::new(\"example1\").unwrap() }"] # ! [doc = ""] # ! [doc = "     fn node_id(&'a self, n: &Nd) -> dot::Id<'a> {"] # ! [doc = "         dot::Id::new(format!(\"N{}\", *n)).unwrap()"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl<'a> dot::GraphWalk<'a> for Edges {"] # ! [doc = "     type Node = Nd;"] # ! [doc = "     type Edge = Ed;"] # ! [doc = "     fn nodes(&self) -> dot::Nodes<'a,Nd> {"] # ! [doc = "         // (assumes that |N| \\approxeq |E|)"] # ! [doc = "         let &Edges(ref v) = self;"] # ! [doc = "         let mut nodes = Vec::with_capacity(v.len());"] # ! [doc = "         for &(s,t) in v {"] # ! [doc = "             nodes.push(s); nodes.push(t);"] # ! [doc = "         }"] # ! [doc = "         nodes.sort();"] # ! [doc = "         nodes.dedup();"] # ! [doc = "         nodes.into()"] # ! [doc = "     }"] # ! [doc = ""] # ! [doc = "     fn edges(&'a self) -> dot::Edges<'a,Ed> {"] # ! [doc = "         let &Edges(ref edges) = self;"] # ! [doc = "         (&edges[..]).into()"] # ! [doc = "     }"] # ! [doc = ""] # ! [doc = "     fn source(&self, e: &Ed) -> Nd { let &(s,_) = e; s }"] # ! [doc = ""] # ! [doc = "     fn target(&self, e: &Ed) -> Nd { let &(_,t) = e; t }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " # pub fn main() { render_to(&mut Vec::new()) }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " # pub fn render_to<W:std::io::Write>(output: &mut W) { unimplemented!() }"] # ! [doc = " pub fn main() {"] # ! [doc = "     use std::fs::File;"] # ! [doc = "     let mut f = File::create(\"example1.dot\").unwrap();"] # ! [doc = "     render_to(&mut f)"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Output from first example (in `example1.dot`):"] # ! [doc = ""] # ! [doc = " ```dot"] # ! [doc = " digraph example1 {"] # ! [doc = "     N0[label=\"N0\"];"] # ! [doc = "     N1[label=\"N1\"];"] # ! [doc = "     N2[label=\"N2\"];"] # ! [doc = "     N3[label=\"N3\"];"] # ! [doc = "     N4[label=\"N4\"];"] # ! [doc = "     N0 -> N1[label=\"\"];"] # ! [doc = "     N0 -> N2[label=\"\"];"] # ! [doc = "     N1 -> N3[label=\"\"];"] # ! [doc = "     N2 -> N3[label=\"\"];"] # ! [doc = "     N3 -> N4[label=\"\"];"] # ! [doc = "     N4 -> N4[label=\"\"];"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " The second example illustrates using `node_label` and `edge_label` to"] # ! [doc = " add labels to the nodes and edges in the rendered graph. The graph"] # ! [doc = " here carries both `nodes` (the label text to use for rendering a"] # ! [doc = " particular node), and `edges` (again a list of `(source,target)`"] # ! [doc = " indices)."] # ! [doc = ""] # ! [doc = " This example also illustrates how to use a type (in this case the edge"] # ! [doc = " type) that shares substructure with the graph: the edge type here is a"] # ! [doc = " direct reference to the `(source,target)` pair stored in the graph's"] # ! [doc = " internal vector (rather than passing around a copy of the pair"] # ! [doc = " itself). Note that this implies that `fn edges(&'a self)` must"] # ! [doc = " construct a fresh `Vec<&'a (usize,usize)>` from the `Vec<(usize,usize)>`"] # ! [doc = " edges stored in `self`."] # ! [doc = ""] # ! [doc = " Since both the set of nodes and the set of edges are always"] # ! [doc = " constructed from scratch via iterators, we use the `collect()` method"] # ! [doc = " from the `Iterator` trait to collect the nodes and edges into freshly"] # ! [doc = " constructed growable `Vec` values (rather than using `Cow` as in the"] # ! [doc = " first example above)."] # ! [doc = ""] # ! [doc = " The output from this example renders four nodes that make up the"] # ! [doc = " Hasse-diagram for the subsets of the set `{x, y}`. Each edge is"] # ! [doc = " labeled with the &sube; character (specified using the HTML character"] # ! [doc = " entity `&sube`)."] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " #![feature(rustc_private)]"] # ! [doc = ""] # ! [doc = " use std::io::Write;"] # ! [doc = " use rustc_graphviz as dot;"] # ! [doc = ""] # ! [doc = " type Nd = usize;"] # ! [doc = " type Ed<'a> = &'a (usize, usize);"] # ! [doc = " struct Graph { nodes: Vec<&'static str>, edges: Vec<(usize,usize)> }"] # ! [doc = ""] # ! [doc = " pub fn render_to<W: Write>(output: &mut W) {"] # ! [doc = "     let nodes = vec![\"{x,y}\",\"{x}\",\"{y}\",\"{}\"];"] # ! [doc = "     let edges = vec![(0,1), (0,2), (1,3), (2,3)];"] # ! [doc = "     let graph = Graph { nodes: nodes, edges: edges };"] # ! [doc = ""] # ! [doc = "     dot::render(&graph, output).unwrap()"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl<'a> dot::Labeller<'a> for Graph {"] # ! [doc = "     type Node = Nd;"] # ! [doc = "     type Edge = Ed<'a>;"] # ! [doc = "     fn graph_id(&'a self) -> dot::Id<'a> { dot::Id::new(\"example2\").unwrap() }"] # ! [doc = "     fn node_id(&'a self, n: &Nd) -> dot::Id<'a> {"] # ! [doc = "         dot::Id::new(format!(\"N{}\", n)).unwrap()"] # ! [doc = "     }"] # ! [doc = "     fn node_label(&self, n: &Nd) -> dot::LabelText<'_> {"] # ! [doc = "         dot::LabelText::LabelStr(self.nodes[*n].into())"] # ! [doc = "     }"] # ! [doc = "     fn edge_label(&self, _: &Ed<'_>) -> dot::LabelText<'_> {"] # ! [doc = "         dot::LabelText::LabelStr(\"&sube;\".into())"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl<'a> dot::GraphWalk<'a> for Graph {"] # ! [doc = "     type Node = Nd;"] # ! [doc = "     type Edge = Ed<'a>;"] # ! [doc = "     fn nodes(&self) -> dot::Nodes<'a,Nd> { (0..self.nodes.len()).collect() }"] # ! [doc = "     fn edges(&'a self) -> dot::Edges<'a,Ed<'a>> { self.edges.iter().collect() }"] # ! [doc = "     fn source(&self, e: &Ed<'_>) -> Nd { let & &(s,_) = e; s }"] # ! [doc = "     fn target(&self, e: &Ed<'_>) -> Nd { let & &(_,t) = e; t }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " # pub fn main() { render_to(&mut Vec::new()) }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " # pub fn render_to<W:std::io::Write>(output: &mut W) { unimplemented!() }"] # ! [doc = " pub fn main() {"] # ! [doc = "     use std::fs::File;"] # ! [doc = "     let mut f = File::create(\"example2.dot\").unwrap();"] # ! [doc = "     render_to(&mut f)"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " The third example is similar to the second, except now each node and"] # ! [doc = " edge now carries a reference to the string label for each node as well"] # ! [doc = " as that node's index. (This is another illustration of how to share"] # ! [doc = " structure with the graph itself, and why one might want to do so.)"] # ! [doc = ""] # ! [doc = " The output from this example is the same as the second example: the"] # ! [doc = " Hasse-diagram for the subsets of the set `{x, y}`."] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " #![feature(rustc_private)]"] # ! [doc = ""] # ! [doc = " use std::io::Write;"] # ! [doc = " use rustc_graphviz as dot;"] # ! [doc = ""] # ! [doc = " type Nd<'a> = (usize, &'a str);"] # ! [doc = " type Ed<'a> = (Nd<'a>, Nd<'a>);"] # ! [doc = " struct Graph { nodes: Vec<&'static str>, edges: Vec<(usize,usize)> }"] # ! [doc = ""] # ! [doc = " pub fn render_to<W: Write>(output: &mut W) {"] # ! [doc = "     let nodes = vec![\"{x,y}\",\"{x}\",\"{y}\",\"{}\"];"] # ! [doc = "     let edges = vec![(0,1), (0,2), (1,3), (2,3)];"] # ! [doc = "     let graph = Graph { nodes: nodes, edges: edges };"] # ! [doc = ""] # ! [doc = "     dot::render(&graph, output).unwrap()"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl<'a> dot::Labeller<'a> for Graph {"] # ! [doc = "     type Node = Nd<'a>;"] # ! [doc = "     type Edge = Ed<'a>;"] # ! [doc = "     fn graph_id(&'a self) -> dot::Id<'a> { dot::Id::new(\"example3\").unwrap() }"] # ! [doc = "     fn node_id(&'a self, n: &Nd<'a>) -> dot::Id<'a> {"] # ! [doc = "         dot::Id::new(format!(\"N{}\", n.0)).unwrap()"] # ! [doc = "     }"] # ! [doc = "     fn node_label(&self, n: &Nd<'_>) -> dot::LabelText<'_> {"] # ! [doc = "         let &(i, _) = n;"] # ! [doc = "         dot::LabelText::LabelStr(self.nodes[i].into())"] # ! [doc = "     }"] # ! [doc = "     fn edge_label(&self, _: &Ed<'_>) -> dot::LabelText<'_> {"] # ! [doc = "         dot::LabelText::LabelStr(\"&sube;\".into())"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl<'a> dot::GraphWalk<'a> for Graph {"] # ! [doc = "     type Node = Nd<'a>;"] # ! [doc = "     type Edge = Ed<'a>;"] # ! [doc = "     fn nodes(&'a self) -> dot::Nodes<'a,Nd<'a>> {"] # ! [doc = "         self.nodes.iter().map(|s| &s[..]).enumerate().collect()"] # ! [doc = "     }"] # ! [doc = "     fn edges(&'a self) -> dot::Edges<'a,Ed<'a>> {"] # ! [doc = "         self.edges.iter()"] # ! [doc = "             .map(|&(i,j)|((i, &self.nodes[i][..]),"] # ! [doc = "                           (j, &self.nodes[j][..])))"] # ! [doc = "             .collect()"] # ! [doc = "     }"] # ! [doc = "     fn source(&self, e: &Ed<'a>) -> Nd<'a> { let &(s,_) = e; s }"] # ! [doc = "     fn target(&self, e: &Ed<'a>) -> Nd<'a> { let &(_,t) = e; t }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " # pub fn main() { render_to(&mut Vec::new()) }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " # pub fn render_to<W:std::io::Write>(output: &mut W) { unimplemented!() }"] # ! [doc = " pub fn main() {"] # ! [doc = "     use std::fs::File;"] # ! [doc = "     let mut f = File::create(\"example3.dot\").unwrap();"] # ! [doc = "     render_to(&mut f)"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # References"] # ! [doc = ""] # ! [doc = " * [Graphviz](https://www.graphviz.org/)"] # ! [doc = ""] # ! [doc = " * [DOT language](https://www.graphviz.org/doc/info/lang.html)"] # ! [allow (internal_features)] # ! [doc (html_root_url = "https://doc.rust-lang.org/nightly/nightly-rustc/" , test (attr (allow (unused_variables) , deny (warnings))))] # ! [doc (rust_logo)] # ! [feature (rustdoc_internals)] use split_decls_genesis :: ourprelude :: * ; use std :: borrow :: Cow ; use std :: io ; use std :: io :: prelude :: * ; use LabelText :: * ; #[doc = " The text for a graphviz label on a node or edge."] pub enum LabelText < 'a > { #[doc = " This kind of label preserves the text directly as is."] #[doc = ""] #[doc = " Occurrences of backslashes (`\\`) are escaped, and thus appear"] #[doc = " as backslashes in the rendered label."] LabelStr (Cow < 'a , str >) , #[doc = " This kind of label uses the graphviz label escString type:"] #[doc = " <https://www.graphviz.org/docs/attr-types/escString>"] #[doc = ""] #[doc = " Occurrences of backslashes (`\\`) are not escaped; instead they"] #[doc = " are interpreted as initiating an escString escape sequence."] #[doc = ""] #[doc = " Escape sequences of particular interest: in addition to `\\n`"] #[doc = " to break a line (centering the line preceding the `\\n`), there"] #[doc = " are also the escape sequences `\\l` which left-justifies the"] #[doc = " preceding line and `\\r` which right-justifies it."] EscStr (Cow < 'a , str >) , #[doc = " This uses a graphviz [HTML string label][html]. The string is"] #[doc = " printed exactly as given, but between `<` and `>`. **No"] #[doc = " escaping is performed.**"] #[doc = ""] #[doc = " [html]: https://www.graphviz.org/doc/info/shapes.html#html"] HtmlStr (Cow < 'a , str >) , } #[doc = " The style for a node or edge."] #[doc = " See <https://www.graphviz.org/docs/attr-types/style/> for descriptions."] #[doc = " Note that some of these are not valid for edges."] #[derive (Copy , Clone , PartialEq , Eq , Debug)] pub enum Style { None , Solid , Dashed , Dotted , Bold , Rounded , Diagonals , Filled , Striped , Wedged , } impl Style { pub fn as_slice (self) -> & 'static str { match self { Style :: None => "" , Style :: Solid => "solid" , Style :: Dashed => "dashed" , Style :: Dotted => "dotted" , Style :: Bold => "bold" , Style :: Rounded => "rounded" , Style :: Diagonals => "diagonals" , Style :: Filled => "filled" , Style :: Striped => "striped" , Style :: Wedged => "wedged" , } } } #[doc = " `Id` is a Graphviz `ID`."] pub struct Id < 'a > { name : Cow < 'a , str > , } impl < 'a > Id < 'a > { #[doc = " Creates an `Id` named `name`."] #[doc = ""] #[doc = " The caller must ensure that the input conforms to an"] #[doc = " identifier format: it must be a non-empty string made up of"] #[doc = " alphanumeric or underscore characters, not beginning with a"] #[doc = " digit (i.e., the regular expression `[a-zA-Z_][a-zA-Z_0-9]*`)."] #[doc = ""] #[doc = " (Note: this format is a strict subset of the `ID` format"] #[doc = " defined by the DOT language. This function may change in the"] #[doc = " future to accept a broader subset, or the entirety, of DOT's"] #[doc = " `ID` format.)"] #[doc = ""] #[doc = " Passing an invalid string (containing spaces, brackets,"] #[doc = " quotes, ...) will return an empty `Err` value."] pub fn new < Name : Into < Cow < 'a , str > > > (name : Name) -> Result < Id < 'a > , () > { let name = name . into () ; match name . chars () . next () { Some (c) if c . is_ascii_alphabetic () || c == '_' => { } _ => return Err (()) , } if ! name . chars () . all (| c | c . is_ascii_alphanumeric () || c == '_') { return Err (()) ; } Ok (Id { name }) } pub fn as_slice (& 'a self) -> & 'a str { & self . name } } #[doc = " Each instance of a type that implements `Label<C>` maps to a"] #[doc = " unique identifier with respect to `C`, which is used to identify"] #[doc = " it in the generated .dot file. They can also provide more"] #[doc = " elaborate (and non-unique) label text that is used in the graphviz"] #[doc = " rendered output."] #[doc = " The graph instance is responsible for providing the DOT compatible"] #[doc = " identifiers for the nodes and (optionally) rendered labels for the nodes and"] #[doc = " edges, as well as an identifier for the graph itself."] pub trait Labeller < 'a > { type Node ; type Edge ; #[doc = " Must return a DOT compatible identifier naming the graph."] fn graph_id (& 'a self) -> Id < 'a > ; #[doc = " Maps `n` to a unique identifier with respect to `self`. The"] #[doc = " implementor is responsible for ensuring that the returned name"] #[doc = " is a valid DOT identifier."] fn node_id (& 'a self , n : & Self :: Node) -> Id < 'a > ; #[doc = " Maps `n` to one of the [graphviz `shape` names][1]. If `None`"] #[doc = " is returned, no `shape` attribute is specified."] #[doc = ""] #[doc = " [1]: https://www.graphviz.org/doc/info/shapes.html"] fn node_shape (& 'a self , _node : & Self :: Node) -> Option < LabelText < 'a > > { None } #[doc = " Maps `n` to a label that will be used in the rendered output."] #[doc = " The label need not be unique, and may be the empty string; the"] #[doc = " default is just the output from `node_id`."] fn node_label (& 'a self , n : & Self :: Node) -> LabelText < 'a > { LabelStr (self . node_id (n) . name) } #[doc = " Maps `e` to a label that will be used in the rendered output."] #[doc = " The label need not be unique, and may be the empty string; the"] #[doc = " default is in fact the empty string."] fn edge_label (& 'a self , _e : & Self :: Edge) -> LabelText < 'a > { LabelStr ("" . into ()) } #[doc = " Maps `n` to a style that will be used in the rendered output."] fn node_style (& 'a self , _n : & Self :: Node) -> Style { Style :: None } #[doc = " Maps `e` to a style that will be used in the rendered output."] fn edge_style (& 'a self , _e : & Self :: Edge) -> Style { Style :: None } } #[doc = " Escape tags in such a way that it is suitable for inclusion in a"] #[doc = " Graphviz HTML label."] pub fn escape_html (s : & str) -> String { s . replace ('&' , "&amp;") . replace ('\"' , "&quot;") . replace ('<' , "&lt;") . replace ('>' , "&gt;") . replace ('\n' , "<br align=\"left\"/>") } impl < 'a > LabelText < 'a > { pub fn label < S : Into < Cow < 'a , str > > > (s : S) -> LabelText < 'a > { LabelStr (s . into ()) } pub fn html < S : Into < Cow < 'a , str > > > (s : S) -> LabelText < 'a > { HtmlStr (s . into ()) } fn escape_char < F > (c : char , mut f : F) where F : FnMut (char) , { match c { '\\' => f (c) , _ => { for c in c . escape_default () { f (c) } } } } fn escape_str (s : & str) -> String { let mut out = String :: with_capacity (s . len ()) ; for c in s . chars () { LabelText :: escape_char (c , | c | out . push (c)) ; } out } #[doc = " Renders text as string suitable for a label in a .dot file."] #[doc = " This includes quotes or suitable delimiters."] pub fn to_dot_string (& self) -> String { match * self { LabelStr (ref s) => format ! ("\"{}\"" , s . escape_default ()) , EscStr (ref s) => format ! ("\"{}\"" , LabelText :: escape_str (s)) , HtmlStr (ref s) => format ! ("<{s}>") , } } } pub type Nodes < 'a , N > = Cow < 'a , [N] > ; pub type Edges < 'a , E > = Cow < 'a , [E] > ; #[doc = " GraphWalk is an abstraction over a directed graph = (nodes,edges)"] #[doc = " made up of node handles `N` and edge handles `E`, where each `E`"] #[doc = " can be mapped to its source and target nodes."] #[doc = ""] #[doc = " The lifetime parameter `'a` is exposed in this trait (rather than"] #[doc = " introduced as a generic parameter on each method declaration) so"] #[doc = " that a client impl can choose `N` and `E` that have substructure"] #[doc = " that is bound by the self lifetime `'a`."] #[doc = ""] #[doc = " The `nodes` and `edges` method each return instantiations of"] #[doc = " `Cow<[T]>` to leave implementors the freedom to create"] #[doc = " entirely new vectors or to pass back slices into internally owned"] #[doc = " vectors."] pub trait GraphWalk < 'a > { type Node : Clone ; type Edge : Clone ; #[doc = " Returns all the nodes in this graph."] fn nodes (& 'a self) -> Nodes < 'a , Self :: Node > ; #[doc = " Returns all of the edges in this graph."] fn edges (& 'a self) -> Edges < 'a , Self :: Edge > ; #[doc = " The source node for `edge`."] fn source (& 'a self , edge : & Self :: Edge) -> Self :: Node ; #[doc = " The target node for `edge`."] fn target (& 'a self , edge : & Self :: Edge) -> Self :: Node ; } #[derive (Clone , PartialEq , Eq , Debug)] pub enum RenderOption { NoEdgeLabels , NoNodeLabels , NoEdgeStyles , NoNodeStyles , Fontname (String) , DarkTheme , } #[doc = " Renders directed graph `g` into the writer `w` in DOT syntax."] #[doc = " (Simple wrapper around `render_opts` that passes a default set of options.)"] pub fn render < 'a , N , E , G , W > (g : & 'a G , w : & mut W) -> io :: Result < () > where N : Clone + 'a , E : Clone + 'a , G : Labeller < 'a , Node = N , Edge = E > + GraphWalk < 'a , Node = N , Edge = E > , W : Write , { render_opts (g , w , & []) } #[doc = " Renders directed graph `g` into the writer `w` in DOT syntax."] #[doc = " (Main entry point for the library.)"] pub fn render_opts < 'a , N , E , G , W > (g : & 'a G , w : & mut W , options : & [RenderOption]) -> io :: Result < () > where N : Clone + 'a , E : Clone + 'a , G : Labeller < 'a , Node = N , Edge = E > + GraphWalk < 'a , Node = N , Edge = E > , W : Write , { writeln ! (w , "digraph {} {{" , g . graph_id () . as_slice ()) ? ; let mut graph_attrs = Vec :: new () ; let mut content_attrs = Vec :: new () ; let font ; if let Some (fontname) = options . iter () . find_map (| option | { if let RenderOption :: Fontname (fontname) = option { Some (fontname) } else { None } }) { font = format ! (r#"fontname="{fontname}""#) ; graph_attrs . push (& font [..]) ; content_attrs . push (& font [..]) ; } if options . contains (& RenderOption :: DarkTheme) { graph_attrs . push (r#"bgcolor="black""#) ; graph_attrs . push (r#"fontcolor="white""#) ; content_attrs . push (r#"color="white""#) ; content_attrs . push (r#"fontcolor="white""#) ; } if ! (graph_attrs . is_empty () && content_attrs . is_empty ()) { writeln ! (w , r#"    graph[{}];"# , graph_attrs . join (" ")) ? ; let content_attrs_str = content_attrs . join (" ") ; writeln ! (w , r#"    node[{content_attrs_str}];"#) ? ; writeln ! (w , r#"    edge[{content_attrs_str}];"#) ? ; } let mut text = Vec :: new () ; for n in g . nodes () . iter () { write ! (w , "    ") ? ; let id = g . node_id (n) ; let escaped = & g . node_label (n) . to_dot_string () ; write ! (text , "{}" , id . as_slice ()) . unwrap () ; if ! options . contains (& RenderOption :: NoNodeLabels) { write ! (text , "[label={escaped}]") . unwrap () ; } let style = g . node_style (n) ; if ! options . contains (& RenderOption :: NoNodeStyles) && style != Style :: None { write ! (text , "[style=\"{}\"]" , style . as_slice ()) . unwrap () ; } if let Some (s) = g . node_shape (n) { write ! (text , "[shape={}]" , & s . to_dot_string ()) . unwrap () ; } writeln ! (text , ";") . unwrap () ; w . write_all (& text) ? ; text . clear () ; } for e in g . edges () . iter () { let escaped_label = & g . edge_label (e) . to_dot_string () ; write ! (w , "    ") ? ; let source = g . source (e) ; let target = g . target (e) ; let source_id = g . node_id (& source) ; let target_id = g . node_id (& target) ; write ! (text , "{} -> {}" , source_id . as_slice () , target_id . as_slice ()) . unwrap () ; if ! options . contains (& RenderOption :: NoEdgeLabels) { write ! (text , "[label={escaped_label}]") . unwrap () ; } let style = g . edge_style (e) ; if ! options . contains (& RenderOption :: NoEdgeStyles) && style != Style :: None { write ! (text , "[style=\"{}\"]" , style . as_slice ()) . unwrap () ; } writeln ! (text , ";") . unwrap () ; w . write_all (& text) ? ; text . clear () ; } writeln ! (w , "}}") } #[cfg (test)] mod tests ;